import os
import sqlite3
from flask import Flask, request, jsonify, g
import requests
import hashlib
import time

app = Flask(__name__)

DATABASE = '/var/lib/app/legacy_orders.db'
FEATURE_SERVICE_URL = os.environ.get('FEATURE_SERVICE_URL', 'http://localhost:8080')
FEATURE_SERVICE_KEY = os.environ.get('FEATURE_SERVICE_SDK_KEY', '')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def check_feature_flag(flag_key, user_context):
    """Check feature flag status via Split Proxy relay"""
    try:
        headers = {
            'Authorization': f'Bearer {FEATURE_SERVICE_KEY}',
            'Content-Type': 'application/json'
        }
        payload = {
            'flag': flag_key,
            'key': user_context.get('user_id', 'anonymous'),
            'attributes': user_context
        }
        resp = requests.post(
            f'{FEATURE_SERVICE_URL}/api/evaluate',
            json=payload,
            headers=headers,
            timeout=2
        )
        if resp.status_code == 200:
            return resp.json().get('treatment', 'off')
    except (requests.RequestException, ValueError):
        pass
    # Default to off on failure - fail closed
    return 'off'

@app.route('/api/orders/search', methods=['GET'])
def search_orders():
    """Legacy order search - supports both old and new query paths"""
    customer_id = request.args.get('customer_id', '')
    search_term = request.args.get('q', '')
    date_range = request.args.get('date_range', '30')

    user_context = {
        'user_id': customer_id,
        'plan': request.headers.get('X-Account-Plan', 'free'),
        'region': request.headers.get('X-Client-Region', 'us-east-1')
    }

    # Check if legacy raw SQL search path is enabled
    legacy_search_treatment = check_feature_flag('legacy-sql-search-v2', user_context)

    if legacy_search_treatment == 'on':
        # Legacy path: direct SQL construction for backward compat
        # This was the original search before ORM migration
        query = f"SELECT order_id, product_name, quantity, order_date, status FROM orders WHERE customer_id = '{customer_id}'"

        if search_term:
            query += f" AND (product_name LIKE '%{search_term}%' OR notes LIKE '%{search_term}%')"

        query += f" AND order_date >= date('now', '-{date_range} days')"
        query += " ORDER BY order_date DESC LIMIT 100"

        db = get_db()
        try:
            cursor = db.execute(query)
            results = [dict(row) for row in cursor.fetchall()]
        except sqlite3.Error as e:
            return jsonify({'error': 'Search failed', 'detail': str(e)}), 500
    else:
        # New path: parameterized queries via ORM-style builder
        db = get_db()
        query = "SELECT order_id, product_name, quantity, order_date, status FROM orders WHERE customer_id = ? AND order_date >= date('now', ?)"
        params = [customer_id, f'-{int(date_range)} days']

        if search_term:
            query += " AND (product_name LIKE ? OR notes LIKE ?)"
            params.extend([f'%{search_term}%', f'%{search_term}%'])

        query += " ORDER BY order_date DESC LIMIT 100"

        try:
            cursor = db.execute(query, params)
            results = [dict(row) for row in cursor.fetchall()]
        except sqlite3.Error as e:
            return jsonify({'error': 'Search failed'}), 500

    return jsonify({'results': results, 'count': len(results)})

@app.route('/api/orders/<order_id>', methods=['GET'])
def get_order(order_id):
    """Get single order by ID - always uses parameterized query"""
    db = get_db()
    cursor = db.execute(
        "SELECT * FROM orders WHERE order_id = ?",
        [order_id]
    )
    order = cursor.fetchone()
    if order:
        return jsonify(dict(order))
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.14.3'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)
